import sys
import os
import subprocess
import json

def main():
    if len(sys.argv) < 2:
        sys.exit(1)

    command = sys.argv[1]
    args = sys.argv[2:]
    full_args = [command] + args

    cache_file = '.cmd_cache'

    if os.path.exists(cache_file):
        with open(cache_file, 'r') as f:
            try:
                cache = json.load(f)
            except json.JSONDecodeError:
                cache = {}
    else:
        cache = {}

    if full_args in cache:
        print(cache[full_args], end='')
        sys.exit(0)

    try:
        result = subprocess.run(
            [command] + args,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True
        )
        stdout = result.stdout
        stderr = result.stderr

        if result.returncode != 0:
            print(stderr, file=sys.stderr)
            sys.exit(result.returncode)
        else:
            cache[full_args] = stdout
            with open(cache_file, 'w') as f:
                json.dump(cache, f)
            print(stdout, end='')
            sys.exit(0)
    except Exception:
        sys.exit(1)

if __name__ == '__main__':
    main()
